function {{functionName}}(values: number[]): number[] {
    const result = [...values];
    for (let i = 1; i < result.length; i++) {
        const value = result[i];
        let j = i - 1;
        while (j >= 0 && result[j] > value) {
            result[j + 1] = result[j];
            j--;
        }
        result[j + 1] = value;
    }
    return result;
}

function {{functionName}}(graph: Map<string, string[]>, start: string): string[] {
    const visited = new Set<string>([start]);
    const queue: string[] = [start];
    for (let head = 0; head < queue.length; head++) {
        for (const next of graph.get(queue[head]) ?? []) {
            if (!visited.has(next)) {
                visited.add(next);
                queue.push(next);
            }
        }
    }
    return queue;
}

function {{functionName}}(n: number): bigint {
    if (!Number.isSafeInteger(n) || n < 0) {
        throw new Error('n должно быть целым неотрицательным числом');
    }
    let previous = 0n;
    let current = 1n;
    for (let i = 0; i < n; i++) {
        [previous, current] = [current, previous + current];
    }
    return previous;
}

